# The wrist view shows one finger inside and one outside the right bowl's front wall.
# I will lower slightly, close on the rim, and make a small lift to test retention.
obs, used, result = move_ee('right', [0.285, -0.13, 0.945] + q_down, 0.7, max_steps=20)
print('descent', result, used)
if result == 'reached':
    s = obs['state']
    hold = {'right_ee_pose': s['right_ee_pose'], 'left_ee_pose': s['left_ee_pose'], 'right_ee_joint_state': [0.0], 'left_ee_joint_state': s['left_ee_joint_state']}
    ended = False
    for i in range(12):
        obs, reward, terminated, truncated, info = step(hold)
        if terminated or truncated:
            ended = True
            break
    if not ended:
        obs, used, result = servo_translate('right', [0.285, -0.13, 1.015], 0.0, max_steps=25)
        print('lift', result, used, obs['state']['right_ee_pose'])

